import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
RAW_PATH = "/tmp/recon/raw.json"
MAX_TRIES = 60

TOKEN = None


def log(*args):
    print(*args, file=sys.stderr, flush=True)


def get_token():
    global TOKEN
    req = urllib.request.Request(BASE + "/token", method="POST")
    with urllib.request.urlopen(req, timeout=20) as r:
        TOKEN = json.loads(r.read())["token"]
    log("token acquired")
    return TOKEN


def wait_seconds(err, body):
    header = err.headers.get("Retry-After")
    if header:
        try:
            return float(header) + 0.5
        except ValueError:
            pass
    try:
        parsed = json.loads(body)
        for key, value in parsed.items():
            if "retry" in key.lower() and isinstance(value, (int, float)):
                return float(value) + 0.5
    except (ValueError, AttributeError):
        pass
    return 5.0


def call(path, auth=True):
    """GET path, retrying on every kind of failure until it succeeds.

    Returns (status, parsed_json_or_None). A 404 is returned, not retried.
    """
    global TOKEN
    tries = 0
    while True:
        tries += 1
        if tries > MAX_TRIES:
            raise RuntimeError(f"giving up on {path} after {MAX_TRIES} tries")
        if auth and TOKEN is None:
            get_token()
        headers = {"Authorization": "Bearer " + TOKEN} if auth else {}
        req = urllib.request.Request(BASE + path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=20) as r:
                return r.status, json.loads(r.read())
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", "replace")
            if e.code == 404:
                return 404, None
            log(f"HTTP {e.code} on {path} (try {tries}): {body[:300]!r} "
                f"Retry-After={e.headers.get('Retry-After')}")
            if e.code in (401, 403):
                TOKEN = None
                time.sleep(1)
            elif e.code == 429:
                time.sleep(wait_seconds(e, body))
            else:
                time.sleep(min(2 ** tries, 30))
        except (urllib.error.URLError, TimeoutError, ConnectionError, ValueError) as e:
            log(f"transport error on {path} (try {tries}): {e!r}")
            time.sleep(min(2 ** tries, 30))


def next_path(next_value):
    if next_value is None:
        return None
    if next_value.startswith("http"):
        return next_value[next_value.index("/", 8):]
    return next_value


def fetch_all_pages():
    pages = []
    seen_paths = set()
    path = "/orders?page=1"
    while path is not None:
        if path in seen_paths:
            raise RuntimeError(f"pagination loop at {path}")
        seen_paths.add(path)
        status, body = call(path)
        if status != 200:
            raise RuntimeError(f"unexpected status {status} on {path}")
        pages.append({"path": path, "body": body})
        log(f"{path}: {len(body['items'])} items, total_pages={body['total_pages']}, "
            f"next={body['next']}")
        path = next_path(body["next"])
    return pages


def fetch_customers(customer_ids):
    customers = {}
    for cid in sorted(customer_ids):
        status, body = call(f"/customers/{cid}")
        customers[cid] = {"status": status, "body": body}
    return customers


if __name__ == "__main__":
    pages = fetch_all_pages()
    all_items = [item for p in pages for item in p["body"]["items"]]
    log(f"pages fetched: {len(pages)}, listed items: {len(all_items)}")

    qualifying_ids = set()
    for item in all_items:
        if item["status"] == "shipped":
            qualifying_ids.add(item["customer_id"])
    log(f"distinct customers among shipped listings: {len(qualifying_ids)}")

    customers = fetch_customers({item["customer_id"] for item in all_items})
    log(f"customer lookups done: {len(customers)}")

    with open(RAW_PATH, "w") as f:
        json.dump({"pages": pages, "customers": customers}, f)
    log(f"raw data written to {RAW_PATH}")

